cypress_script:
describe('Web Tables CRUD Operations', () => {
  it('should add a new record successfully', () => {
    cy.visit('https://demoqa.com/webtables');
    cy.get('#addNewRecordButton').click();
    // Assuming there are input fields to fill out (not provided in inventory)
    // Fill out the form with valid data
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="age"]').type('30');
    cy.get('input[name="email"]').type('john.doe@example.com');
    cy.get('input[name="salary"]').type('50000');
    cy.get('button[type="submit"]').click();
    // Assert that the new record is visible in the table
    cy.get('table').should('contain', 'John Doe');
  });

  it('should not add a record with empty fields', () => {
    cy.visit('https://demoqa.com/webtables');
    cy.get('#addNewRecordButton').click();
    // Submit the form without filling out any fields
    cy.get('button[type="submit"]').click();
    // Assert that the URL did not change
    cy.url().should('eq', 'https://demoqa.com/webtables');
    // Assert that the table is still visible
    cy.get('table').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Web Tables CRUD Operations', () => {
  test('should add a new record successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
    await page.click('#addNewRecordButton');
    // Assuming there are input fields to fill out (not provided in inventory)
    // Fill out the form with valid data
    await page.fill('input[name="firstName"]', 'John');
    await page.fill('input[name="lastName"]', 'Doe');
    await page.fill('input[name="age"]', '30');
    await page.fill('input[name="email"]', 'john.doe@example.com');
    await page.fill('input[name="salary"]', '50000');
    await page.click('button[type="submit"]');
    // Assert that the new record is visible in the table
    await expect(page.locator('table')).toContainText('John Doe');
  });

  test('should not add a record with empty fields', async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
    await page.click('#addNewRecordButton');
    // Submit the form without filling out any fields
    await page.click('button[type="submit"]');
    // Assert that the URL did not change
    await expect(page).toHaveURL('https://demoqa.com/webtables');
    // Assert that the table is still visible
    await expect(page.locator('table')).toBeVisible();
  });
});
